tr><tr><td>298</td><td>299</td><td>N 56°31'25\" E</td><td>156.77</td><td>299</td><td>2,123,935.048</td><td>627,605.926</td></tr><tr><td>299</td><td>252</td><td>N 56°54'35\" E</td><td>32.82</td><td>252</td><td>2,123,952.969</td><td>627,633.426</td></tr><tr><td colspan=\"7\">SUPERFICIE = 121,575.710 m² (12-15-75.710 has)</td></tr></tbody></table>\n<p>CROQUIS DE UBICACIÓN - POLO DE DESARROLLO ECONÓMICO PARA EL BIENESTAR</p>\n<p>FUTURA CAPITAL DE LA TECNOLOGÍA Y LA SOSTENIBILIDAD</p>\n<p><a href=\"https://dof.gob.mx/abrirPDF.php?anio=2025&amp;archivo=01072025-MAT.pdf&amp;repo=#page=39\">Croquis de ubicación en el PDF oficial · página 39</a></p>","tipo_articulo":"ordinario","orden":3,"titulo_nombre":"Capital de la Tecnología y la Sostenibilidad","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"284b473a-5615-5cd2-9d41-fba1f66b18db","ley_id":"53c8188a-012f-5cc3-ad7c-78be66708faa","identificador":"Artículo tercero","contenido":"<p>ARTÍCULO TERCERO. La superficie a que se refiere el artículo anterior cumple con los Criterios de Selección de los Polos de Desarrollo Económico para el Bienestar, aprobados por el Comité Intersecretarial de Promoción, como a continuación se indica:</p>","tipo_articulo":"ordinario","orden":4,"titulo_nombre":"Capital de la Tecnología y la Sostenibilidad","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"1f7c7a04-b382-5fc7-b329-7095ed63a67b","ley_id":"53c8188a-012f-5cc3-ad7c-78be66708faa","identificador":"Artículo tercero · I. Criterio de Macro Localización","contenido":"<p>I. Criterio de Macro Localización</p>\n<p>El inmueble del Polo de Desarrollo para el Bienestar FUTURA CAPITAL DE LA TECNOLOGÍA Y LA SOSTENIBILIDAD, PUEBLA se localiza en la región centro-oriente del estado de Puebla, una zona estratégica que articula los corredores económicos del altiplano central con el Golfo de México.</p>\n<p>Se ubica a menos de 70 km de la ciudad de Puebla y a unos 40 km del Arco Norte, lo que los conecta de manera eficiente con el Valle de México, Tlaxcala, Veracruz y el puerto de Veracruz.</p>","tipo_articulo":"ordinario","orden":5,"titulo_nombre":"Capital de la Tecnología y la Sostenibilidad","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"d79ce758-271c-5bee-9e75-e73be0832f91","ley_id":"53c8188a-012f-5cc3-ad7c-78be66708faa","identificador":"Artículo tercero · II. Criterio de Comunicación y Conectividad","contenido":"<p>II. Criterio de Comunicación y Conectividad</p>\n<p>El inmueble del Polo de Desarrollo para el Bienestar FUTURA CAPITAL DE LA TECNOLOGÍA Y SOSTENIBILIDAD, PUEBLA cuenta con una ubicación estratégica en materia de comunicación y conectividad regional, al situarse en el eje que articula el altiplano central con el Golfo de México.</p>\n<p>Este polo se encuentra cerca de la autopista Amozoc-Perote y del Arco Norte, dos corredores logísticos clave que permiten la conexión directa con el Valle de México, Veracruz, Tlaxcala y la zona metropolitana de Puebla. Esta infraestructura vial facilita el flujo eficiente de mercancías, insumos y personas, potenciando su integración a cadenas productivas regionales.</p>","tipo_articulo":"ordinario","orden":6,"titulo_nombre":"Capital de la Tecnología y la Sostenibilidad","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"06578b30-5806-57bc-9abb-0190aca745b9","ley_id":"53c8188a-012f-5cc3-ad7c-78be66708faa","identificador":"Artículo tercero · III. Criterio Poblacional","contenido":"<p>III. Criterio Poblacional</p>\n<p>El Polo de Desarrollo para el Bienestar FUTURA CAPITAL DE LA TECNOLOGÍA Y LA SOSTENIBILIDAD, PUEBLA se ubica en los municipios de San José Chiapa y Nopalucan, en el estado de Puebla, cuyos municipios aledaños son: Oriental, San Salvador el Seco y Mazapiltepec de Juárez.</p>\n<p>Conforme al Censo de Población y vivienda 2020, la población total de los municipios mencionados en el párrafo anterior es mayor a 50,000 habitantes.</p>\n<table><thead><tr><th>Municipio Sede y Municipios Aledaños</th><th>Población Censo 2020</th><th>Población Total Municipio Sede y Municipios Aledaños</th></tr></thead><tbody><tr><td>Nopalucan</td><td>32,772</td><td rowspan=\"9\">245,203</td></tr><tr><td>Oriental</td><td>19,903</td></tr><tr><td>San Salvador el Seco</td><td>30,639</td></tr><tr><td>Mazapiltepec de Juárez</td><td>3,176</td></tr><tr><td>Rafael Lara Grajales</td><td>15,952</td></tr><tr><td>San José Chiapa</td><td>10, 443</td></tr><tr><td>El Carmen Tequexquitla</td><td>17,332</td></tr><tr><td>Cuapiaxtla</td><td>16,222</td></tr><tr><td>Huamantla</td><td>98,764</td></tr></tbody></table>","tipo_articulo":"ordinario","orden":7,"titulo_nombre":"Capital de la Tecnología y la Sostenibilidad","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"9e3fc64e-0888-5e2c-ad19-70dd46f5c22a","ley_id":"53c8188a-012f-5cc3-ad7c-78be66708faa","identificador":"Artículo tercero · IV. Criterio de Factibilidad Social","contenido":"<p>IV. Criterio de Factibilidad Social</p>\n<p>El Instituto Nacional de los Pueblos Indígenas mediante oficio CGDI/2025/OF/570, de fecha 5 de junio de 2025, emitió un dictamen sobre la procedencia de la consulta indígena en la superficie destinada al Polo de Desarrollo Económico para el Bienestar FUTURA CAPITAL DE LA TECNOLOGÍA Y LA SOSTENIBILIDAD, PUEBLA decretando lo siguiente:</p>\n<p>\"\"[...] no se identifica comunidad indígena titular del Derecho a la Consulta, resultando innecesario analizar si la medida puede generar posibilidad de afectación y menos aún determinar la procedencia de un proceso de consulta previa, libre e informada por posible afectación a sus derechos territoriales. [...]\"\"</p>","tipo_articulo":"ordinario","orden":8,"titulo_nombre":"Capital de la Tecnología y la Sostenibilidad","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"128a71b0-1271-5848-b5ef-d82652a7cc5b","ley_id":"53c8188a-012f-5cc3-ad7c-78be66708faa","identificador":"Artículo tercero · V. Criterio Educativo","contenido":"<p>V. Criterio Educativo</p>\n<p>En los municipios de San José Chiapa y Nopalucan se localizan las siguientes instituciones de educación siguientes:</p>\n<p>Universidades e Instituciones de Educación Superior</p>\n<table><thead><tr><th>Municipio</th><th>Institución de Educación Superior</th></tr></thead><tbody><tr><td>Oriental</td><td>Universidad Tecnológica de Oriental (UTO)</td></tr><tr><td>Juan C. Bonilla</td><td>Universidad Politécnica de Puebla (UPPue)</td></tr><tr><td>Tepeaca</td><td>Benemérita Universidad Autónoma de Puebla (BUAP) - Campus Tepeaca</td></tr><tr><td>Ahuacatlán</td><td>Universidad Interserrana del Estado de Puebla - Ahuacatlán.</td></tr></tbody></table>\n<p>Instituciones de Educación Media Superior</p>\n<table><thead><tr><th>Municipio</th><th>Institución de Educación Superior</th></tr></thead><tbody><tr><td>San José Chiapa</td><td>Bachillerato Digital No. 62</td></tr><tr><td>Rafael Lara Grajales</td><td>Centro Escolar \"Presidente Lázaro Cárdenas\"</td></tr><tr><td>Nopalucan</td><td>CECyTE Puebla Plantel Nopalucan</td></tr><tr><td>Nopalucan</td><td>Bachillerato General Oficial \"Dr. Rafael Ávila Camacho\"</td></tr></tbody></table>","tipo_articulo":"ordinario","orden":9,"titulo_nombre":"Capital de la Tecnología y la Sostenibilidad","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"949d1954-4ce9-5457-9638-6162e73e2592","ley_id":"53c8188a-012f-5cc3-ad7c-78be66708faa","identificador":"Artículo tercero · VI. Criterio Territorial","contenido":"<p>VI. Criterio Territorial</p>\n<p>Para el desarrollo de las actividades productivas en el Polo de Desarrollo Económico para el Bienestar FUTURA CAPITAL DE LA TECNOLOGÍA Y LA SOSTENIBILIDAD, PUEBLA son vocaciones productivas, prioritarias y potenciales las siguientes:</p>\n<p>1. Manufacturera avanzada</p>\n<p>2. Industria automotriz</p>\n<p>3. Industria textil especializada</p>\n<p>4. Electrónica</p>\n<p>5. Industria química</p>\n<p>6. Industria del plástico y del hule</p>","tipo_articulo":"ordinario","orden":10,"titulo_nombre":"Capital de la Tecnología y la Sostenibilidad","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"d90f8b04-655f-5cf8-906f-c46fe01374a1","ley_id":"53c8188a-012f-5cc3-ad7c-78be66708faa","identificador":"Artículo tercero · VII. Criterio de Factibilidad Industrial","contenido":"<p>VII. Criterio de Factibilidad Industrial</p>\n<p>Mediante oficios MSJCH/OPyDU2025/426 MSJCH/OPyDU2025/427, ambos de fecha 6 de junio de 2025 emitido por el Director de Obras Públicas y Desarrollo Urbano del Municipio de San José Chiapa se informa que el uso de suelo es compatible con el industrial.</p>","tipo_articulo":"ordinario","orden":11,"titulo_nombre":"Capital de la Tecnología y la Sostenibilidad","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"539e265a-2f02-5dd9-b690-119a91fead46","ley_id":"53c8188a-012f-5cc3-ad7c-78be66708faa","identificador":"Artículo tercero · VIII. Criterio de Sostenibilidad","contenido":"<p>VIII. Criterio de Sostenibilidad</p>\n<p>La Secretaría de Medio Ambiente y Recursos Naturales, mediante oficio número SDSEC/800/79/2025 de fecha 3 de junio de 2025, suscrito por el Dr. José Luis Samaniego Leyva, Subsecretario de Desarrollo Sostenible y Economía Circula, determinó que es viable el Polo ya que entre otras características destacan que:</p>\n<p>\"\"[...] El polígono se ubica en zona clasificada como asentamiento humano e industrial, ya impactada y sin vegetación forestal, por lo que no requiere autorización de cambio de uso de suelo en terrenos forestales. [...]\"\"</p>","tipo_articulo":"ordinario","orden":12,"titulo_nombre":"Capital de la Tecnología y la Sostenibilidad","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"3dc33883-4c40-5858-a2e8-69a1de3ea4c6","ley_id":"53c8188a-012f-5cc3-ad7c-78be66708faa","identificador":"Artículo tercero · IX. Criterio de Servicios e Infraestructura","contenido":"<p>IX. Criterio de Servicios e Infraestructura</p>\n<p>El polígono cuenta con los servicios e infraestructura básicos para el desarrollo de las actividades productivas. Dispone de vialidades, energía eléctrica, agua potable, drenaje y conectividad, lo que garantiza condiciones adecuadas para la operación de empresas e industrias, y contribuye al impulso del desarrollo regional y la atracción de inversiones.</p>","tipo_articulo":"ordinario","orden":13,"titulo_nombre":"Capital de la Tecnología y la Sostenibilidad","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"1f15ece4-db72-5c97-8b14-cd6ca0dc1770","ley_id":"53c8188a-012f-5cc3-ad7c-78be66708faa","identificador":"Artículo tercero · X. Criterio de Propiedad","contenido":"<p>X. Criterio de Propiedad</p>\n<p>De conformidad con la información proporcionada por la entidad federativa y la documentación que fue puesta a disposición de este Comité, se desprende que los predios que conforman el área destinada al Polo de Desarrollo para el Bienestar están sujetos a régimen de fideicomiso bajo control del Gobierno del Estado</p>","tipo_articulo":"ordinario","orden":14,"titulo_nombre":"Capital de la Tecnología y la Sostenibilidad","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"75194eaa-db9d-50ef-9649-c54bda5ff761","ley_id":"53c8188a-012f-5cc3-ad7c-78be66708faa","identificador":"Artículo cuarto","contenido":"<p>ARTÍCULO CUARTO. El estado de Puebla y la Secretaría de Economía deberán suscribir el convenio de coordinación a que se refiere el artículo Décimo, párrafo tercero del Decreto por el que se otorgan estímulos fiscales en los Polos de Desarrollo Económico para el Bienestar.</p>","tipo_articulo":"ordinario","orden":15,"titulo_nombre":"Capital de la Tecnología y la Sostenibilidad","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"b4ddda22-0e81-5cd8-8e73-133ebce2f2c0","ley_id":"53c8188a-012f-5cc3-ad7c-78be66708faa","identificador":"Transitorio único","contenido":"<p>TRANSITORIO</p>\n<p>ÚNICO. La presente Declaratoria entrará en vigor el día siguiente al de su publicación en el Diario Oficial de la Federación.</p>","tipo_articulo":"transitorio","orden":16,"titulo_nombre":"Capital de la Tecnología y la Sostenibilidad","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"42b5ec19-7d08-5e3c-97ad-3f290093a369","ley_id":"53c8188a-012f-5cc3-ad7c-78be66708faa","identificador":"Firma del acuerdo","contenido":"<p>Ciudad de México, a diecinueve de junio de 2025.- El Secretario de Economía, Marcelo Luis Ebrard Casaubon.- Rúbrica.</p>","tipo_articulo":"complementario","orden":17,"titulo_nombre":"Capital de la Tecnología y la Sostenibilidad","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"55741c85-4505-5b0d-8c00-5eefb2779fa4","ley_id":"53c8188a-012f-5cc3-ad7c-78be66708faa","identificador":"Notas al pie","contenido":"<p>1 https://www.gob.mx/cms/uploads/attachment/file/981072/PND_2025-2030_v250226_14.pdf</p>","tipo_articulo":"nota","orden":18,"titulo_nombre":"Capital de la Tecnología y la Sostenibilidad","capitulo_nombre":"Declaratoria del polo","seccion_nombre":null},{"id":"1e053ceb-c24c-5d72-843f-21bbb367c469","ley_id":"53c8188a-012f-5cc3-ad7c-78be66708faa","identificador":"Nota editorial · publicación posterior","contenido":"<p>Esta ficha reproduce la declaratoria original. Consulte la publicación posterior en el DOF: <a href=\"https://sidof.segob.gob.mx/notas/docFuente/5764007\">Nota aclaratoria del 29/07/2025</a>.</p>","tipo_articulo":"complementario","orden":19,"titulo_nombre":"Capital de la Tecnología y la Sostenibilidad","capitulo_nombre":"Documentos relacionados","seccion_nombre":null}]}$polo$::jsonb;
  ley jsonb := paquete->'ley';
  ley_uuid uuid := (ley->>'id')::uuid;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended(ley->>'url_original', 0));
  IF EXISTS (SELECT FROM public.leyes WHERE id <> ley_uuid AND (siglas = ley->>'siglas' OR url_original = ley->>'url_original')) THEN
    RAISE EXCEPTION 'Declaratoria registrada con otro ID: %', ley->>'siglas';
  END IF;
  INSERT INTO public.leyes (id, siglas, titulo, tipo, fecha_publicacion, url_original, temas_clave)
  SELECT id, siglas, titulo, tipo, fecha_publicacion, url_original, temas_clave FROM jsonb_populate_record(null::public.leyes, ley)
  ON CONFLICT (id) DO NOTHING;
  INSERT INTO public.articulos (id, ley_id, identificador, contenido, tipo_articulo, orden, titulo_nombre, capitulo_nombre, seccion_nombre)
  SELECT id, ley_id, identificador, contenido, tipo_articulo, orden, titulo_nombre, capitulo_nombre, seccion_nombre
  FROM jsonb_populate_recordset(null::public.articulos, paquete->'articulos') ON CONFLICT (id) DO NOTHING;
  IF NOT EXISTS (SELECT FROM public.leyes l WHERE l.id = ley_uuid AND to_jsonb(l) @> ley)
     OR EXISTS (SELECT FROM jsonb_array_elements(paquete->'articulos') a WHERE NOT EXISTS (
       SELECT FROM public.articulos t WHERE t.id = (a->>'id')::uuid AND to_jsonb(t) @> a)) THEN
    RAISE EXCEPTION 'El registro existente difiere del cotejo de %', ley->>'siglas';
  END IF;
END
$carga$;
